const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: {
  config: {
    dry_run: true,
    metrics_endpoint_url: 'https://CONFIGURE-ME.invalid/metrics/weekly',
    summary_webhook_url: 'https://CONFIGURE-ME.invalid/reports/weekly'
  },
  period: { start: start.toISOString(), end: end.toISOString(), timezone: 'Europe/London' },
  generated_at: end.toISOString()
} }];

const configData = $node['Weekly Report Configuration'].json;
const rawItems = $input.all().map(item => item.json || {});
const rows = [];
for (const raw of rawItems) {
  const candidate = raw.data ?? raw.items ?? raw.records ?? raw.metrics ?? raw;
  if (Array.isArray(candidate)) rows.push(...candidate.filter(v => v && typeof v === 'object'));
  else if (candidate && typeof candidate === 'object') rows.push(candidate);
}
const fields = ['companies_discovered','decision_makers_found','verified_contacts','approved_contacts','enrolled','emails_sent','replies','positive_replies','bounces','unsubscribes','inbound_calls','outbound_calls','qualified_calls','meetings_booked','opportunities','errors'];
const totals = Object.fromEntries(fields.map(field => [field, 0]));
for (const row of rows) {
  for (const field of fields) {
    const value = Number(row[field] ?? 0);
    if (Number.isFinite(value)) totals[field] += value;
  }
}
const rate = (numerator, denominator) => denominator > 0 ? Number(((numerator / denominator) * 100).toFixed(1)) : 0;
const rates = {
  decision_maker_rate_pct: rate(totals.decision_makers_found, totals.companies_discovered),
  verification_rate_pct: rate(totals.verified_contacts, totals.decision_makers_found),
  approval_rate_pct: rate(totals.approved_contacts, totals.verified_contacts),
  enrolment_rate_pct: rate(totals.enrolled, totals.approved_contacts),
  reply_rate_pct: rate(totals.replies, totals.emails_sent),
  positive_reply_rate_pct: rate(totals.positive_replies, totals.replies),
  bounce_rate_pct: rate(totals.bounces, totals.emails_sent),
  meeting_rate_pct: rate(totals.meetings_booked, totals.replies),
  call_qualification_rate_pct: rate(totals.qualified_calls, totals.inbound_calls + totals.outbound_calls)
};
const title = `JavedAI weekly funnel report: ${configData.period.start.slice(0,10)} to ${configData.period.end.slice(0,10)}`;
const summaryText = [
  title,
  `Companies ${totals.companies_discovered} → decision makers ${totals.decision_makers_found} → verified ${totals.verified_contacts} → approved ${totals.approved_contacts} → enrolled ${totals.enrolled}`,
  `Emails sent ${totals.emails_sent}; replies ${totals.replies} (${rates.reply_rate_pct}%); positive ${totals.positive_replies}; bounces ${totals.bounces} (${rates.bounce_rate_pct}%); unsubscribes ${totals.unsubscribes}`,
  `Calls inbound ${totals.inbound_calls}; outbound ${totals.outbound_calls}; qualified ${totals.qualified_calls}; meetings ${totals.meetings_booked}; opportunities ${totals.opportunities}; workflow errors ${totals.errors}`
].join('\n');
return [{ json: { status: 'ready', period: configData.period, generated_at: new Date().toISOString(), totals, rates, title, summary_text: summaryText, config: configData.config, source_row_count: rows.length } }];
